Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
xen-netback: reject zero-queue configuration from guest

A malicious or buggy Xen guest can write "0" to the xenbus key
"multi-queue-num-queues". The connect() function in the backend only
validates the upper bound (requested_num_queues > xenvif_max_queues)
but not zero, allowing requested_num_queues=0 to reach
vzalloc(array_size(0, sizeof(struct xenvif_queue))), which triggers
WARN_ON_ONCE(!size) in __vmalloc_node_range().

On systems with panic_on_warn=1, this allows a guest-to-host denial
of service.

The Xen network interface specification requires
the queue count to be "greater than zero".

Add a zero check to match the validation already present
in xen-blkback, which has included this
guard since its multi-queue support was added.

Fixes: 8d3d53b3e433 ("xen-netback: Add support for multiple queues")
Signed-off-by: Ziyi Guo <n7l8m4@u.northwestern.edu>
Reviewed-by: Juergen Gross <jgross@suse.com>
Link: https://patch.msgid.link/20260212224040.86674-1-n7l8m4@u.northwestern.edu
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The validation in the `connect()` function only checks if the requested number of queues exceeds the maximum (`xenvif_max_queues`), but does not check for a value of zero. This allows a malicious or buggy guest to set `multi-queue-num-queues` to 0, which passes the existing check and reaches `vzalloc(array_size(0, sizeof(struct xenvif_queue)))`. This triggers a kernel warning (`WARN_ON_ONCE(!size)`) in `__vmalloc_node_range()`, and on systems with `panic_on_warn=1`, causes a denial of service.

Here is the patch:

 static void connect(struct backend_info *be)
 {
 	int err;
 	struct xenbus_device *dev = be->dev;
 	unsigned long credit_bytes, credit_usec;
 	unsigned int queue_index;
 	unsigned int requested_num_queues;
 	struct xenvif_queue *queue;

 	/* Check whether the frontend requested multiple queues
 	 * and read the number requested.
 	 */
 	requested_num_queues = xenbus_read_unsigned(dev->otherend,
 					"multi-queue-num-queues", 1);
-	if (requested_num_queues > xenvif_max_queues) {
+	if (requested_num_queues > xenvif_max_queues ||
+	    requested_num_queues == 0) {
 		/* buggy or malicious guest */
 		xenbus_dev_fatal(dev, -EINVAL,
-				 "guest requested %u queues, exceeding the maximum of %u.",
+				 "guest requested %u queues, but valid range is 1 - %u.",
 				 requested_num_queues, xenvif_max_queues);
 		return;
 	}

 	err = xen_net_read_mac(dev, be->vif->fe_dev_addr);
 	if (err) {
 		xenbus_dev_fatal(dev, err, "parsing %s/mac", dev->nodename);
 		return;
 	}

 	xen_net_read_rate(dev, &credit_bytes, &credit_usec);
 	xen_unregister_watchers(be->vif);
 	xen_register_watchers(dev, be->vif);
 	read_xenbus_vif_flags(be);

 	err = connect_ctrl_ring(be);
 	if (err) {
 		xenbus_dev_fatal(dev, err, "connecting control ring");
 		return;
 	}

 	/* Use the number of queues requested by the frontend */
 	be->vif->queues = vzalloc(array_size(requested_num_queues,
 					     sizeof(struct xenvif_queue)));
 	if (!be->vif->queues) {
 		xenbus_dev_fatal(dev, -ENOMEM,
 				 "allocating queues");
 		return;
 	}

 	be->vif->num_queues = requested_num_queues;
 	be->vif->stalled_queues = requested_num_queues;

 	for (queue_index = 0; queue_index < requested_num_queues; ++queue_index) {
 		queue = &be->vif->queues[queue_index];
 		queue->vif = be->vif;
 		queue->id = queue_index;
 		snprintf(queue->name, sizeof(queue->name), "%s-q%u",
 				be->vif->dev->name, queue->id);

 		err = xenvif_init_queue(queue);
 		if (err) {
 			/* xenvif_init_queue() cleans up after itself on
 			 * failure, but we need to clean up any previously
 			 * initialised queues. Set num_queues to i so that
 			 * earlier queues can be destroyed using the regular
 			 * disconnect logic.
 			 */
 			be->vif->num_queues = queue_index;
 			goto err;
 		}

 		queue->credit_bytes = credit_bytes;
 		queue->remaining_credit = credit_bytes;
 		queue->credit_usec = credit_usec;

 		err = connect_data_rings(be, queue);
 		if (err) {
 			/* connect_data_rings() cleans up after itself on
 			 * failure, but we need to clean up after
 			 * xenvif_init_queue() here, and also clean up any
 			 * previously initialised queues.
 			 */
 			xenvif_deinit_queue(queue);
 			be->vif->num_queues = queue_index;
 			goto err;
 		}
 	}

 #ifdef CONFIG_DEBUG_FS
 	xenvif_debugfs_addif(be->vif);
 #endif /* CONFIG_DEBUG_FS */

 	/* Initialisation completed, tell core driver the number of
 	 * active queues.
 	 */
 	rtnl_lock();
 	netif_set_real_num_tx_queues(be->vif->dev, requested_num_queues);
 	netif_set_real_num_rx_queues(be->vif->dev, requested_num_queues);
 	rtnl_unlock();

 	xenvif_carrier_on(be->vif);

 	unregister_hotplug_status_watch(be);
 	err = xenbus_watch_pathfmt(dev, &be->hotplug_status_watch, NULL,
 				   hotplug_status_changed,
 				   "%s/%s", dev->nodename, "hotplug-status");
 	if (!err)
 		be->have_hotplug_status_watch = 1;

 	netif_tx_wake_all_queues(be->vif->dev);

 	return;

 err:
 	if (be->vif->num_queues > 0)
 		xenvif_disconnect_data(be->vif); /* Clean up existing queues */
 	for (queue_index = 0; queue_index < be->vif->num_queues; ++queue_index)
 		xenvif_deinit_queue(&be->vif->queues[queue_index]);
 	vfree(be->vif->queues);
 	be->vif->queues = NULL;
 	be->vif->num_queues = 0;
 	xenvif_disconnect_ctrl(be->vif);
 	return;
 }



